import fs from 'node:fs';
import path from 'node:path';
import { verifyReceipt } from '../src/index';

// Conformance: the SDK verifier gives the verdict recorded in docs/protocol/vectors/receipt.json (family v2-receipt) for every case.
// The vectors are generated by scripts/protocol/gen-receipt-vectors.js and re-derived by the Node and Python independent verifiers.
const file = path.join(__dirname, '..', '..', '..', 'docs', 'protocol', 'vectors', 'receipt.json');
const vectors = JSON.parse(fs.readFileSync(file, 'utf8')) as {
  keys: Array<{ keyId: string; publicKeySpkiB64: string; status: string; revokedAt?: number }>;
  cases: Array<{ id: string; description: string; input: { receipt: unknown; trustedAt?: number }; expected?: { outcome: 'ok' }; expectedError?: { code: string } }>;
};
const keys = vectors.keys.map((k) => ({ keyId: k.keyId, publicKey: k.publicKeySpkiB64, status: k.status, revokedAt: k.revokedAt }));

describe('receipt conformance vectors (V2-RECEIPT-*)', () => {
  it('has the pinned minimum of cases', () => { expect(vectors.cases.length).toBeGreaterThanOrEqual(48); });
  it.each(vectors.cases.map((c) => [c.id, c.description, c] as const))('%s %s', (_id, _d, c) => {
    const got = verifyReceipt(c.input.receipt, keys, c.input.trustedAt === undefined ? {} : { trustedAt: c.input.trustedAt });
    if (c.expectedError) expect(got).toEqual({ ok: false, reason: c.expectedError.code });
    else expect(got).toEqual({ ok: true, reason: null });
  });
});
